INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$The same task affects people's awareness of their surroundings differently. Math puzzles make most people more aware. Some people, the ones who picture the numbers, become *less* aware while solving. Others may become more aware because their brains signal a rest after each stage.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. "Most people" become more aware, and "some people" become less aware. Put those together: puzzles don't raise everyone's awareness. That is the safe inference, and it comes straight from the long third sentence.$batch07$), (2, $batch07$Goal$batch07$, $batch07$For some people, math puzzles don't increase environmental awareness.$batch07$)) v(position,label,body) WHERE e.id=$batch07$331fa775-17e7-439b-ba4b-1ada37e6874e$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
